        { 2040, "A", 15, 20, "Shoni the Shilent", "Stormwind City - Dwarven District 62,34", "Shoni the Shilent", false, {2041}, {7606, 7607, 270015, 270016}, "Retrieve the Compact High-Energy Engine from the Deadmines and bring it to Shoni the Shilent in the Dwarven District of Stormwind City.", "这个任务可以直接接，也可以先做诺恩(铁炉堡-侏儒区 69,50)给的引导任务。发动机由斯尼德的伐木机掉落。", {{15,1}, {16,2}, {18,3}, {23,4}, {27,5}}, {7365}, nil, 6579, "Shoni the Shilent", { xp = 1550, rep = { {72, 100, "Stormwind City"}, {54, 100, "Gnomeregan Exiles"} } } },
