        { 1048, "H", 33, 42, "Varimathras", "Undercity - Royal Quarter 56,92", nil, false, nil, {6802, 6803, 10711}, "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod the Champion and Houndmaster Loksey, then report back to Varimathras in the Undercity.", "Whitemane and Mograine are in the Cathedral, Herod in the Armory, Loksey in the Library.", {{33,1}, {38,2}, {40,3}, {45,4}, {52,5}}, nil, nil, 2425, "Varimathras", { xp = 5150, rep = { {68, 200, "Undercity"} } } },
