    ["the_drowned_city"] = {
        { 96774, "H", 30, 40, "Mazu'kon", "Mulgore 32.4,20.6", nil, false, nil, nil, "Recover an Ancient Gurubashi Idol from the most impressive-looking priest in the Drowned City and bring it to Mazu'kon in Mulgore.", "起始在副本外(莫高雷 32.4,20.6，疑为雷霆崖)；马祖空，开始并结束于同处；神像由副本内牧师造型首领掉落。", {{30,1}, {36,2}, {38,3}, {43,4}, {51,5}}, {276894}, nil, 264074, "Mazu'kon", { xp = 8800, money = 10000, rep = { {76, 150, "Darkspear Trolls"} } } },
