    ["uldaman"] = {
        { 1192, nil, 29, nil, "Pozzik", "Thousand Needles - Mirage Raceway 80.1, 75.9", "Indurium Ore", false, {1194}, nil, "Collect 4 refined iron ore for Pozzik of the Thousand Needles.", "Repeatable after the prerequisite; gives only a little money, no reputation or experience. The ore can be mined inside Uldaman or bought from other players.", {{29,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {5833}, nil, 4630, "Pozzik", nil },
        { 704, "A", 30, 38, "Prospector Ironband", "Loch Modan - Ironband's Excavation 65,65", "Agmond's Fate", false, {739}, {4980}, "Collect 4 Carved Stone Urns and bring them to Prospector Ironband of Loch Modan.", "系列始于勘察员塔伯斯·雷矛(铁炉堡-探险者大厅 74,12)。石罐散落在副本前的山洞里。", {{30,1}, {34,2}, {36,3}, {41,4}, {47,5}}, {4610}, nil, 1344, "Prospector Ironband", { xp = 2850, rep = { {47, 100, "Ironforge"} } } },
        { 709, nil, 30, 40, "Theldurin the Lost", "Badlands 51,76", nil, false, nil, {4746}, "Bring the Rewuna Stone Tablet to Theldurin the Lost.", "The tablet is at the end of the passage in the north end of the cave.", {{30,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {4631}, nil, 2785, "Theldurin the Lost", { xp = 3150 } },
        { 2418, nil, 30, 36, "Rigglefuzz", "Badlands 42,52", nil, false, nil, {9522, 10358, 10359}, "Collect 8 Detiam Power Stones and 8 Annalom Power Stones for Rigglefuzz of the Badlands.", "Dark Iron enemies inside and outside the dungeon drop the power stones. No need to enter the dungeon — killing the Dark Iron dwarves at the dig site outside the entrance is enough.", {{30,1}, {32,2}, {34,3}, {39,4}, {45,5}}, {8009, 8052}, nil, 2817, "Rigglefuzz", { xp = 3500, rep = { {21, 150, "Booty Bay"}, {87, 750, "Bloodsail Buccaneers"} } } },
        { 1360, "A", 33, 43, "Krom Stoutarm", "Ironforge - Hall of Explorers 74,9", nil, false, nil, nil, "Find Krom Stoutarm's Chest in the northern hall of Uldaman, take the treasure inside, and bring it back to him in Ironforge.", "The treasure is in the cave before the dungeon, at the end of the first passage to the southeast in the north.", {{33,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {8027}, nil, 6294, "Krom Stoutarm", { xp = 3600, money = 6000, rep = { {47, 100, "Ironforge"} } } },
        { 2342, "H", 33, 43, "Patrick Garrett", "Undercity 72,48", nil, false, nil, nil, "Recover Garrett's family treasure from the chest in the southern hall of Uldaman and bring it to Patrick Garrett in the Undercity.", "The treasure can be reached before entering the dungeon, at the end of the southern passage.", {{33,1}, {39,2}, {41,3}, {46,4}, {53,5}}, {8026}, nil, 5651, "Patrick Garrett", { xp = 3600, money = 6000, rep = { {68, 100, "Undercity"} } } },
        { 721, "A", 35, nil, "Prospector Ryedol", "Badlands 53,43", "Amulet of Secrets", false, {720}, nil, "Enter Uldaman and find Hammertoe Grez.", "系列始于一张弄皱的地图(荒芜之地 53,33)。铁趾格雷兹在副本入口附近。", {{35,3}, {38,4}, {44,5}}, nil, nil, 2910, "Prospector Ryedol", nil },
        { 722, "A", 35, 40, "Hammertoe Grez", "Uldaman (dungeon-entrance map).", "Amulet of Secrets", false, {721}, nil, "Retrieve Hammertoe's amulet and bring it to Hammertoe Grez in Uldaman.", "The amulet drops from Magregan Deepshadow.", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {4635}, nil, 2909, "Hammertoe Grez", { xp = 3150, rep = { {47, 100, "Ironforge"} } } },
        { 1139, "A", 35, 45, "Advisor Belgrum", "Ironforge - Hall of Explorers 77,10", "The Lost Tablets of Will", false, {762}, {6723}, "Find the Tablet of Resolve and bring it to Advisor Belgrum in Ironforge.", "The tablet is inside the dungeon, right beside Galgann Firehammer.", {{35,1}, {41,2}, {43,3}, {48,4}, {55,5}}, {5824}, nil, 2918, "Advisor Belgrum", { xp = 5850, money = 13000, rep = { {47, 200, "Ironforge"} } } },
        { 1956, nil, 35, nil, "Tabetha", "Dustwallow Marsh 46,57", "Exorcism", false, {1955}, nil, "Find an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", "仅法师可做！能量源由黑曜石哨兵掉落。黑曜石哨兵就在后门里——从后门(荒芜之地 67,44)进去第一眼就能看到，没有小怪护卫。", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, {8053}, "Mage", 6546, "Tabetha", nil },
        { 2240, "A", 35, 40, "Baelog", "Uldaman", "The Hidden Chamber", true, {2398}, {9626, 9627}, "Read Baelog's diary, uncover the hidden chamber, then report back to Prospector Tabor Stormpike in Ironforge.", "The Hidden Chamber is inside the instance. Opening procedure: get the Shaft of Tsol from Revelosh and the Gni'kiv Medallion from Baelog's chest, combine them into the Staff of Prehistoria; then use it in the Map Room between the two halls to summon Ironaya — defeat her and enter the Hidden Chamber.", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 6906, "Baelog", { xp = 3900, rep = { {47, 150, "Ironforge"} } } },
        { 2398, "A", 35, nil, "Prospector Stormpike", "Ironforge - Hall of Explorers 75,12", nil, false, nil, nil, "Find Baelog inside Uldaman.", "Ballog is inside the dungeon. Breadcrumb quest: it cannot be completed if you have already accepted or completed 'The Hidden Chamber'.", {{35,1}, {36,2}, {38,3}, {43,4}, {49,5}}, nil, nil, 1356, "Prospector Stormpike", nil },
        { 17, "A", 36, 42, "Ghak Healtouch", "Loch Modan - Thelsamar 37,49", "Uldaman Reagent Run", false, {2500}, {9030}, "Collect 12 Purple Lotuses and bring them back to Ghak Healtouch in Thelsamar.", "The Magenta Fungus Caps are scattered in the cave BEFORE the instance (not inside), mostly by campfires and behind tents; with Herbalism tracking on they show up on the minimap. The prerequisite quest is taken from the same NPC.", {{38,2}, {40,3}, {45,4}, {52,5}}, {8047}, nil, 1470, "Ghak Healtouch", { xp = 3450, money = 5500, rep = { {47, 100, "Ironforge"} } } },
        { 2202, "H", 36, 42, "Jarkal Mossmeld", "Badlands - Kargath 2,69", "Uldaman Reagent Run", false, {2258}, {9030}, "Collect 12 Purple Lotuses and bring them to Jarkal Mossmeld in Kargath.", "The prerequisite is also taken from Jarkal Mossmeld. The mushrooms are scattered throughout the dungeon; Find Herbs marks them on the minimap.", {{36,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {8047}, nil, 6868, "Jarkal Mossmeld", { xp = 3450, money = 5500, rep = { {530, 100, "Darkspear Trolls"} } } },
        { 2198, "A", 37, 41, "The Shattered Necklace", "Random drop inside Uldaman", nil, false, nil, nil, "Find out the history of the Broken Necklace and assess its value.", "把项链带给铁炉堡的塔瓦斯德·基瑟尔(铁炉堡-秘法区 36,3)。", {{37,2}, {39,3}, {44,4}, {51,5}}, {7666}, nil, nil, nil, { xp = 3300 } },
        { 2199, "A", 37, 41, "Talvash del Kissel", "Dun Morogh", nil, false, {2198}, nil, nil, nil, {{37,2}, {39,3}, {44,4}, {51,5}}, {2842}, nil, 6826, "Talvash del Kissel", { xp = 2450, rep = { {54, 75, "Gnomeregan Exiles"} } } },
        { 2200, "A", 37, nil, "Talvash del Kissel", "Ironforge - Mystic Ward 36,3", "Back to Uldaman", false, {2199}, nil, "Search Uldaman for Talvash's magic necklace — a dead paladin was its last holder.", "The paladin is inside the dungeon: the body is in the northwest corner of the Hall of the Keepers (the first sideways-'8' shaped area), marked with a yellow '?' — no searching required.", {{37,1}, {38,2}, {40,3}, {45,4}, {52,5}}, {7667}, nil, 6826, "Talvash del Kissel", nil },
        { 2204, "A", 37, 44, "Talvash's Divining Bowl", "Talvash's Divining Bowl", "Restoring the Necklace", true, {2201}, nil, "Take the power source from the strongest stone golem of Uldaman and bring it to Talvash in Ironforge.", "The necklace's power source drops from Archaedas.", {{37,1}, {40,2}, {42,3}, {47,4}, {54,5}}, {7672}, nil, nil, nil, { xp = 930 } },
        { 2283, "H", 37, 41, "Dran Droffers", "Orgrimmar - Rogue Quarter 59,36", nil, false, nil, nil, "Look for a valuable necklace (possibly damaged) at the Uldaman excavation and bring it to Dran Droffers in Orgrimmar.", "The necklace is a random drop inside the dungeon.", {{37,2}, {39,3}, {44,4}, {51,5}}, {7666}, nil, 6986, "Dran Droffers", { xp = 2450, rep = { {76, 75, "Orgrimmar"} } } },
