        { 8990, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "More Vital Materials", false, {8985}, nil, "Use the summoning brazier to call out Isalien's spirit and kill it; return the brazier and Duke Vatalak's trinket to Bodley.", "You need the Extraplanar Ghost Revealer to see Bodley (from \"Finding Anthion\"). Isalien is summoned inside the instance.", {{58,3}, {63,4}, {72,5}}, {22048, 22050}, nil, 16033, "Bodley", { xp = 8300 } },
