    ["scholomance"] = {
        { 5341, "H", 52, 60, "Alexi Barov", "Tirisfal Glades - The Bulwark 80,73", nil, false, nil, nil, "Recover the four Barov family deeds from Scholomance (Caer Darrow, Brill, Tarren Mill and Southshore) and return them to Alexi Barov.", "Deed locations: Caer Darrow = in the first hall after entering; Southshore = on the desk in the left corner of the first large hall after crossing the bridge; Tarren Mill = on the desk in the right corner of the room before the whelps; Brill = in the room where Ras Frostwhisper is.", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13471, 13448, 13450, 13451}, nil, 11022, "Alexi Barov", { xp = 6600, money = 18000 } },
        { 5343, "A", 52, 60, "Weldon Barov", "Western Plaguelands - Chillwind Camp 43,83", nil, false, nil, nil, "Recover the four Barov family deeds from Scholomance (Caer Darrow, Brill, Tarren Mill and Southshore) and return them to Weldon Barov.", "Deed locations: Caer Darrow = in the first hall after entering; Southshore = on the desk in the left corner of the first large hall after crossing the bridge; Tarren Mill = on the desk in the right corner of the room before the whelps; Brill = in the room where Ras Frostwhisper is.", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13471, 13448, 13450, 13451}, nil, 11023, "Weldon Barov", { xp = 6600, money = 18000 } },
        { 5382, nil, 55, 60, "Eva Sarkhoff", "Western Plaguelands - Caer Darrow 70,73", nil, false, nil, nil, "Find Doctor Theolen Krastinov in Scholomance, kill him and burn the remains of Eva Sarkhoff and Lucien Sarkhoff, then report back to Eva Sarkhoff.", "After the doctor dies, look at the piles of flesh on both sides of the room — the remains of Eva and Lucien Sarkhoff are inside; clear them to complete.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11216, "Eva Sarkhoff", { xp = 6600 } },
        { 5384, nil, 55, 60, "Eva Sarkhoff", "Western Plaguelands - Caer Darrow 70,73", "Krastinov's Bag of Horrors", false, {5515}, {15805, 15806, 13544}, "Bring the Blood of Innocents back to Scholomance and pour it into the brazier on the porch to draw out Kirtonos the Herald; face him bravely and do not flinch. Kill him and report back to Eva Sarkhoff.", "The vestibule is inside the dungeon. The Blood of Innocents drops 100% from the succubus in the first room; if the summoned Kirtonos doesn't drop the reward you want, abandon and re-take the quest (the instance must be reset to summon again).", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13523}, nil, 11216, "Eva Sarkhoff", { xp = 8300 } },
        { 5515, nil, 55, 60, "Eva Sarkhoff", "Western Plaguelands - Caer Darrow 70,73", "Doctor Theolen Krastinov", false, {5382}, nil, "Defeat Jandice Barov in Scholomance, take Krastinov's Bag of Horrors from her corpse and bring it to Eva Sarkhoff.", "Jandice Barov is inside the dungeon. Only the real body has a health bar among the clones — turn on nameplates (V) or mark the real one, and only hit the one with the bar.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13725}, nil, 11216, "Eva Sarkhoff", { xp = 6600 } },
        { 5529, nil, 55, 58, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 76,54", nil, false, nil, nil, "Kill 20 Plague Dragon Whelps and report back to Betina Bigglezink at Light's Hope Chapel.", "The Plague Dragon Whelps are in the bone vault — the big chamber on the way to the Bloodbone Golem.", {{55,2}, {56,3}, {61,4}, {69,5}}, nil, nil, 11035, "Betina Bigglezink", { xp = 6200, money = 9000, rep = { {529, 100, "Argent Dawn"} } } },
        { 5582, nil, 55, nil, "Healthy Dragon Scale", "Random drop from Plaguebats in Scholomance", "Healthy Dragon Scale", false, {5529}, nil, "Bring the Healthy Dragon Scale to Betina Bigglezink at Light's Hope Chapel in Eastern Plaguelands.", "要先完成《瘟疫龙崽》才会出现可采的健康龙鳞（否则看不见）。健康的龙鳞由瘟疫龙崽掉落（约 8%）。贝蒂娜·比格辛克(东瘟疫之地-圣光之愿礼拜堂 76,54)。", {{55,2}, {56,3}, {61,4}, {69,5}}, {13920}, nil, nil, nil, nil },
        { 4771, nil, 57, 60, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 77,54", "Betina Bigglezink", false, {5531}, {15853, 15854}, "Place the Dawn's Gambit in the Viewing Room of Scholomance, defeat Vectus, then report back to Betina Bigglezink.", "前置《雏龙精华》始于丁奇·斯迪波尔(燃烧平原-烈焰峰 65,23)。观察室在副本内。", {{57,2}, {58,3}, {63,4}, {72,5}}, {12368}, nil, 11035, "Betina Bigglezink", { xp = 9950, money = 27000, rep = { {529, 200, "Argent Dawn"} } } },
        { 5466, nil, 57, 60, "Magistrate Marduke", "Western Plaguelands - Caer Darrow 70,73", "The Lich, Ras Frostwhisper", false, {5465}, {13982, 13986, 13984, 14002}, "Find Ras Frostwhisper in Scholomance and use the Soulbound Keepsake to break his undead shell; once it works, kill him and bring his head to Magistrate Marduke.", "Ras Frostwhisper is inside the instance.", {{57,2}, {58,3}, {63,4}, {72,5}}, {13626, 13752}, nil, 11286, "Magistrate Marduke", { xp = 9950 } },
        { 5531, nil, 57, 60, "Leonid Barthalomew the Revered", "Eastern Plaguelands", "Leonid Barthalomew the Revered", false, {5522}, nil, nil, nil, {{57,2}, {58,3}, {63,4}, {72,5}}, {13761}, nil, 11036, "Leonid Barthalomew the Revered", { xp = 1650, rep = { {529, 25, "Argent Dawn"} } } },
        { 8258, "H", 58, nil, "Sagorne Creststrider", "Orgrimmar - Valley of Wisdom 38.6, 36.2", "The Darkreaver Menace", false, {7667}, nil, "Use the Divination Scryer at the center of the bone vault in Scholomance's basement and defeat the summoned ghosts; when Death Knight Darkreaver appears, defeat him too and take his head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar.", "Shaman-only quest; the prerequisite is taken from the same NPC. Darkreaver is summoned inside the instance.", {{58,3}, {63,4}, {72,5}}, {18880, 18746}, "Shaman", nil, nil, nil },
        { 8969, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "Vital Materials", false, {8965}, nil, "Use the summoning brazier to call out Kormok's spirit and kill him; return the brazier and the left half of the Vatalak Trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Kormok is inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22052}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8992, nil, 58, 60, "Bodley", "Blackrock Mountain dungeon-entrance map [D]", "More Vital Materials", false, {8988}, nil, "Use the summoning brazier to call out Kormok's spirit and kill him; return the brazier and Duke Vatalak's trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). Kormok is inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {22048, 22052}, nil, 16033, "Bodley", { xp = 8300 } },
        { 7629, nil, 60, nil, "Gorzeeki Wildeyes", "Burning Steppes 12,31", "Imp Delivery", false, {7625}, nil, "Take the imp in the bottle to the alchemy lab in Scholomance; once it produces the parchment, return the bottle to Gorzeeki Wildeyes.", "Warlock only! The alchemy lab is in the same room as Ras Frostwhisper.", {{60,3}, {4,4}, {6,5}}, {18688}, "Warlock", 14437, "Gorzeeki Wildeyes", nil },
        { 7647, nil, nil, nil, nil, nil, nil, false, {7646}, nil, nil, nil, {{60,3}, {4,4}, {6,5}}, {18799, 18792, 18804}, "Paladin", 928, "Lord Grayson Shadowbreaker", nil },
    },
    ["stratholme_main"] = {
        { 5305, nil, 50, nil, "Lilith the Lithe", "Winterspring - Everlook 61,37", nil, false, nil, nil, "Kill the Crimson Hammerer in Stratholme and bring his apron to Lilith the Lithe.", "The Crimson Hammersmith is a triggered spawn: click the 'Blacksmithing Plans' parchment on the ground to trigger it.", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13351}, nil, 11191, "Lilith the Lithe", nil },
        { 5307, nil, 50, nil, "Seril Scourgebane", "Winterspring - Everlook 61,37", nil, false, nil, nil, "Find and kill the Black Guard Swordsmith in Stratholme and bring the Black Guard Medallion to Seril Scourgebane.", "The Dark Iron Guardsmith is a triggered spawn: click the 'Blacksmithing Plans' parchment on the ground next to the pawn shop beside Anastari's ziggurat.", {{50,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13350}, nil, 11193, "Seril Scourgebane", nil },
        { 5848, nil, 52, 60, "Artist Renfray", "Western Plaguelands - Caer Darrow 65,75", "Of Love and Family", false, {5846}, nil, "到斯坦索姆的血色十字军堡垒找回名画《爱与家庭》——它藏在另一幅双月之画的后面——把画归还给提里奥·弗丁。", "前置从提里奥·弗丁处接(西瘟疫之地 7,43)。画在活人区档案室进门右手边。", {{52,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {14679}, nil, 11936, "Artist Renfray", { xp = 6600 } },
        { 5125, nil, 55, 60, "Aurius", "Stratholme", "Aurius' Reckoning", true, {"Aurius' Reckoning"}, {17044, 17045}, "Kill Baron Rivendare.", "First give Aurius [Aurius' Reckoning] (the medallion is inside Malor's Strongbox in the instance); he will join the fight against the Baron but will fall. After killing the Baron, talk to his corpse to complete the quest.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 10917, "Aurius", { xp = 9950 } },
        { 5212, nil, 55, nil, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 76,54", nil, false, nil, nil, "Recover 20 Plagued Flesh Samples from Stratholme and bring them to Betina Bigglezink.", "Most enemies in Stratholme drop the flesh samples, but the drop rate is low.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13174}, nil, 11035, "Betina Bigglezink", { xp = 6600, money = 18000, rep = { {529, 100, "Argent Dawn"} } } },
        { 5213, nil, 55, 60, "Betina Bigglezink", "Eastern Plaguelands - Light's Hope Chapel 76,54", "The Active Agent", false, {5212}, {13209, 19812}, "Search the ziggurats of Stratholme for the new Scourge archive and bring it to Betina Bigglezink.", "The small box spawns randomly in ONE of the three ziggurats (Nerub'enkan, Baroness Anastari, Maleki); it does not disappear — every party member can loot it.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13176}, nil, 11035, "Betina Bigglezink", { xp = 6600, rep = { {529, 100, "Argent Dawn"} } } },
        { 5214, nil, 55, 60, "Smokey LaRue", "Eastern Plaguelands - Light's Hope Chapel 75,52", nil, false, nil, {13171}, "Find Fras Siabi's tobacco shop in Stratholme, retrieve a box of Siabi's Tobacco and bring it to Smokey LaRue.", "The tobacco shop is inside the dungeon: keep turning left to the dead end, to the right of the well — clear everything along the way. Fras Siabi appears the moment you open the box.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13172}, nil, 11033, "Smokey LaRue", { xp = 8300 } },
        { 5243, nil, 55, 60, "Leonid Barthalomew the Revered", "Eastern Plaguelands - Light's Hope Chapel 76,52", nil, false, nil, {13216, 13217, 3928, 6149}, "Head to Stratholme, loot the supply crates scattered around the city, collect 5 Stratholme Holy Water and report back to Leonid Barthalomew the Revered.", "The holy water is in crates all over the city; some are fakes that burst into a swarm of bugs. Dwarves can use 'Find Treasure' to mark the real crates on the minimap.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13180}, nil, 11036, "Leonid Barthalomew the Revered", { xp = 6600, money = 18000, rep = { {529, 100, "Argent Dawn"} } } },
        { 5251, nil, 55, 60, "Duke Nicholas Zverenhoff", "Eastern Plaguelands - Light's Hope Chapel 76,52", nil, false, nil, nil, "Find the Scarlet crusade's Archivist Galford in Stratholme, kill him and burn the Scarlet Crusade archives.", "The archives and the Archivist are both inside the dungeon. ◎ If you are also doing 'Of Love And Family': grab the painting BEFORE burning the archives — the painting burns together with them.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, nil, nil, 11039, "Duke Nicholas Zverenhoff", { xp = 8300, money = 18000, rep = { {529, 150, "Argent Dawn"} } } },
        { 5262, nil, 55, 60, "Balnazzar", "Stratholme", "The Truth Comes Crashing Down", false, nil, nil, "Bring Balnazzar's head to Duke Nicholas Zverenhoff in Eastern Plaguelands.", "公爵(东瘟疫之地-圣光之愿礼拜堂 76,52)。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13250}, nil, nil, nil, { xp = 8300, rep = { {529, 150, "Argent Dawn"} } } },
        { 5263, nil, 55, nil, "Duke Nicholas Zverenhoff", "Eastern Plaguelands - Light's Hope Chapel 76,52", "Above and Beyond", false, {5262}, nil, "Kill Baron Rivendare in Stratholme and bring his head to Duke Nicholas Zverenhoff.", "The Baron is inside the instance. This quest has a follow-up that grants the reward.", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13251}, nil, 11039, "Duke Nicholas Zverenhoff", { xp = 8300, rep = { {529, 150, "Argent Dawn"} } } },
        { 5282, nil, 55, 60, "Egan", "Eastern Plaguelands 11,29", "The Restless Souls", false, {5281}, {13315}, "Use Egan's Blaster on the ghostly residents of Stratholme; use it once more after their souls leave the bodies to put them to rest for good. Free 15 Restless Souls and report back to Egan.", "前置从护理者奥林处接(东瘟疫之地-圣光之愿礼拜堂 74,58)。鬼魂居民在城中到处游荡。冲击枪打中鬼魂约 10 秒后其身边会出现「不安的灵魂」，对它再补一枪即可拾取。", {{55,1}, {56,2}, {58,3}, {63,4}, {72,5}}, {13289}, nil, 11140, "Egan", { xp = 8300, money = 18000 } },
        { 6163, "H", 56, nil, "Nathanos Blightcaller", "Eastern Plaguelands 22,68", "Ramstein", false, {6135}, nil, "Kill Ramstein the Gorger in Stratholme and bring his head to Nathanos.", "The prerequisite is likewise taken from Nathanos. Ramstein is inside the instance.", {{56,2}, {58,3}, {63,4}, {72,5}}, {15880}, nil, 11878, "Nathanos Blightcaller", { xp = 6600, money = 18000, rep = { {68, 100, "Undercity"} } } },
        { 5463, nil, 57, 60, "Leonid Barthalomew the Revered", "Eastern Plaguelands - Light's Hope Chapel 75,52", "Menethil's Gift", false, {5462}, nil, "Find Menethil's Gift in Stratholme and place the lich's mortal remains on that evil ground.", "前置从马杜克镇长处接(西瘟疫之地-凯尔达隆 70,73)。标记就是男爵房间地上的五芒星。另见通灵学院的「巫妖莱斯·霜语」。", {{57,2}, {58,3}, {63,4}, {72,5}}, {13585}, nil, 11036, "Leonid Barthalomew the Revered", { xp = 6600 } },
        { 8945, nil, 58, 60, "Ysida Harmon", "Eastern Plaguelands - Stratholme", "Dead Man's Plea", false, {8929}, {22137}, "Enter Stratholme and rescue Ysida Harmon from Baron Rivendare.", "伊思达·哈尔蒙就站在副本门口，需要超维度幽灵显形器才能看到他。前置：联盟找德莉亚娜(铁炉堡 43,52)，部落找莫克瓦尔(奥格瑞玛 38,37)。这也是著名的「45 分钟瑞文戴尔」任务。", {{58,3}, {63,4}, {72,5}}, nil, nil, 16016, "Anthion Harmon", { xp = 8300 } },
        { 8968, nil, 58, 60, "Bodley", "Blackrock Mountain - dungeon entrance map [D]", "Vital Materials", false, {8964}, nil, "Use the summoning brazier to call out the spirits of Jarien and Sothos and kill them; return the brazier and the left half of the Vatalak Trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The two are summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {21984, 22051}, nil, 16033, "Bodley", { xp = 8300 } },
        { 8991, nil, 58, 60, "Bodley", "Blackrock Mountain - dungeon entrance map [D]", "More Vital Materials", false, {8987}, nil, "Use the summoning brazier to call out the spirits of Jarien and Sothos and kill them; return the brazier and Duke Vatalak's trinket to Bodley at Blackrock Mountain.", "You need the Extraplanar Ghost Revealer to see Bodley (from 'Finding Anthion'). The two are summoned inside the dungeon.", {{58,3}, {63,4}, {72,5}}, {22048, 22051}, nil, 16033, "Bodley", { xp = 8300 } },
        { 7622, nil, 60, nil, "Eris Havenfire", "Eastern Plaguelands 17,14", "The Balance of Light and Shadow", false, {7621}, nil, "Save 50 farmers before 15 of them are killed, then talk to Eris Havenfire when done. The death notices show your rescue progress.", "You need the Eye of Divinity (from the chest of the Firelord in Molten Core) to meet Eris Havenfire and take the quest. On completion, combine the Eye of Divinity, the Splinter of Nordrassil and the Eye of Shadow (random demon drops in Blasted Lands / Winterspring) to obtain the priest epic staff — Benediction.", {{60,3}, {63,4}, {72,5}}, nil, "Priest", 14494, "Eris Havenfire", nil },
        { 9257, nil, 60, nil, "Anachronos", "Tanaris - Caverns of Time 65,49", "Atiesh, Greatstaff of the Guardian", false, {9251}, nil, "Anachronos of the Caverns of Time in Tanaris wants you to travel to Stratholme, use Atiesh, Greatstaff of the Guardian on the hallowed ground, defeat the creatures driven out, then report back to him.", "The summoning spot is inside the instance. In the Wrath of the Lich King expansion this quest can no longer be obtained; only the \"summon Atiesh\" step remains completable.", {{60,3}, {63,4}, {72,5}}, {22737}, "Priest", nil, nil, nil },
    },
