    [155] = { lv = 14, lvStd = 18, nm = "Red Silk Bandanas", npc = "The Defias Traitor", npcid = 467, side = "A", zone = "Westfall", gains = { xp = 1700, rep = { { 72, 150, "Stormwind City" } } }, obj = "护送迪菲亚叛徒前往迪菲亚兄弟会的秘密藏身处。迪菲亚叛徒把你带到范克里夫和他的手下的巢穴之后，尽快回去向格里安·斯托曼汇报相关信息。", text = "护送迪菲亚叛徒前往月溪镇的迪菲亚藏身处，他会带路，路上别让他死；抵达后回哨兵岭向斯托曼复命。" },
